import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Auto-Load Token 預算守衛 — 深度研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-04-token-guardian-research.md","filePath":"research/reports/archive/2026-06-04-token-guardian-research.md","lastUpdated":1780842316000}'),s={name:"research/reports/archive/2026-06-04-token-guardian-research.md"};function n(l,e,i,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="auto-load-token-預算守衛-—-深度研究報告" tabindex="-1">Auto-Load Token 預算守衛 — 深度研究報告 <a class="header-anchor" href="#auto-load-token-預算守衛-—-深度研究報告" aria-label="Permalink to &quot;Auto-Load Token 預算守衛 — 深度研究報告&quot;">​</a></h1><blockquote><p><strong>日期</strong>：2026-06-04 <strong>分支</strong>：feature/insights-horizon-research <strong>來源</strong>：<code>/insights</code> On-the-Horizon 機會 #3 <strong>落點判定</strong>：<strong>擴展既有 3 處</strong>（measure.sh + autoload-evolution SKILL + memory-compactor）——非新建（違 R2）。 <strong>方法</strong>：1 researcher 深研 + 主對話機械重驗。</p></blockquote><hr><h2 id="_0-問題陳述" tabindex="-1">0. 問題陳述 <a class="header-anchor" href="#_0-問題陳述" aria-label="Permalink to &quot;0. 問題陳述&quot;">​</a></h2><p>每次變更量測 auto-load byte、強制 hard cap，並把 prune 內容 diff 對照 value-scored allowlist，永不靜默丟掉高價值 lessons，超 cap 或會丟保護內容時需使用者確認。</p><p><strong>真實痛點（一手）</strong>：</p><ul><li><strong>auto-load 現況 18,455 byte / cap 19,000，餘裕 545（近滿）</strong>（機械重驗確認）。</li><li><strong>memory-compactor over-pruned 靜默丟 12 高價值 Lessons</strong>，靠後續機械驗證才抓到。</li><li><strong>三源 cap 定義曾矛盾</strong>（core.md byte vs README/measure.sh token + stale 數字，Lesson 2026-05-31f-B）。</li></ul><hr><h2 id="_1-核心發現-6-點" tabindex="-1">1. 核心發現（6 點） <a class="header-anchor" href="#_1-核心發現-6-點" aria-label="Permalink to &quot;1. 核心發現（6 點）&quot;">​</a></h2><h3 id="f1-—-兩個獨立-prune-面-現有機制各有缺口" tabindex="-1">F1 — 兩個獨立 prune 面，現有機制各有缺口 <a class="header-anchor" href="#f1-—-兩個獨立-prune-面-現有機制各有缺口" aria-label="Permalink to &quot;F1 — 兩個獨立 prune 面，現有機制各有缺口&quot;">​</a></h3><ul><li><strong>面 A — auto-load byte cap</strong>（5 檔）：<code>measure.sh --gate</code> 已做 byte &gt;19,000 阻擋 + §R-header 存活（<code>RB_CORE==11</code>，<strong>機械重驗確認</strong> measure.sh L88-94）。但 §R header 只確認 11 個標題存在，<strong>不驗證條文內容是否為 stub</strong>。<code>healthcheck.sh</code> <strong>完全不呼叫 measure.sh --gate</strong>（機械重驗：<code>grep -c measure.sh scripts/healthcheck.sh</code> = 0），兩者斷開。</li><li><strong>面 B — MEMORY/refs compaction</strong>（memory-compactor Haiku agent）：「永不移除」清單只是 LLM 指令，無機械驗證。MEMORY #448「先 grep 確認 C1/C2 錨點實質存活非 stub」是人工補位。<strong>守衛核心價值在此面，不在 byte cap</strong>。</li></ul><blockquote><p>來源：親讀 healthcheck.sh（0 measure 引用）+ measure.sh L88-96 [HIGH]</p></blockquote><h3 id="f2-—-auto-load-slimming-→-memory-耦合靜默丟失鏈" tabindex="-1">F2 — auto-load slimming → MEMORY 耦合靜默丟失鏈 <a class="header-anchor" href="#f2-—-auto-load-slimming-→-memory-耦合靜默丟失鏈" aria-label="Permalink to &quot;F2 — auto-load slimming → MEMORY 耦合靜默丟失鏈&quot;">​</a></h3><p>auto-load 精簡把歷史 demote 到 MEMORY/refs，依賴 MEMORY 作持久層。若 memory-compactor 隨後 over-prune，內容從兩處同時消失。value-score allowlist 需同時覆蓋兩面。</p><blockquote><p>來源：MEMORY L166 [HIGH，repo]</p></blockquote><h3 id="f3-—-autoload-evolution-skill-md-仍有三源漂移-live-非假設" tabindex="-1">F3 — autoload-evolution SKILL.md 仍有三源漂移（live，非假設） <a class="header-anchor" href="#f3-—-autoload-evolution-skill-md-仍有三源漂移-live-非假設" aria-label="Permalink to &quot;F3 — autoload-evolution SKILL.md 仍有三源漂移（live，非假設）&quot;">​</a></h3><p>SKILL.md L31/97/112/209 硬寫 <code>13,000</code>（<strong>機械重驗確認 4 處</strong>）；core.md §Framework Integrity 及 measure.sh L77 現行 cap 為 <code>19,000</code>。Lesson 2026-05-31f-B（三源矛盾）正在復發。守衛需「canonical 來源唯一性」驗證，SKILL.md 是已確認的修正目標。</p><blockquote><p>來源：主對話 <code>grep -n &quot;13,000&quot; .claude/skills/autoload-evolution/SKILL.md</code> → L31/97/112/209 [HIGH]</p></blockquote><h3 id="f4-—-§r-survival-原語已存在-守衛是泛化而非新建-r2-支持" tabindex="-1">F4 — §R-survival 原語已存在，守衛是泛化而非新建（R2 支持） <a class="header-anchor" href="#f4-—-§r-survival-原語已存在-守衛是泛化而非新建-r2-支持" aria-label="Permalink to &quot;F4 — §R-survival 原語已存在，守衛是泛化而非新建（R2 支持）&quot;">​</a></h3><p><code>measure.sh --gate</code> 的 <code>grep -c &quot;^## §R&quot; core.md == 11</code> 是機械化 allowlist 原語。守衛是把這模式從「header 存在」泛化到「diff 後 anchor 內容非 stub + MEMORY Lesson 行未被移除」。無需新 SKILL。</p><blockquote><p>來源：measure.sh L89-91 [HIGH]</p></blockquote><h3 id="f5-—-fail-open-約束-使用者確認門不能放-pretooluse-hook" tabindex="-1">F5 — fail-open 約束：使用者確認門不能放 PreToolUse hook <a class="header-anchor" href="#f5-—-fail-open-約束-使用者確認門不能放-pretooluse-hook" aria-label="Permalink to &quot;F5 — fail-open 約束：使用者確認門不能放 PreToolUse hook&quot;">​</a></h3><p>MEMORY Lesson 2026-06-04-B + branch-isolation-guard.sh：共用 PreToolUse hook 必 fail-open（exit 0 + warn），否則阻擋背景自動化 commit。因此 <strong>user-confirm gate 只能活在互動式 autoload-evolution flow</strong>（人在場的 Phase 4→5），共用 hook 只能 warn。</p><blockquote><p>來源：MEMORY Lesson 2026-06-04-B [HIGH]</p></blockquote><h3 id="f6-—-外部工具-sota-有-cap-無-value-scored-allowlist" tabindex="-1">F6 — 外部工具 SOTA：有 cap 無 value-scored allowlist <a class="header-anchor" href="#f6-—-外部工具-sota-有-cap-無-value-scored-allowlist" aria-label="Permalink to &quot;F6 — 外部工具 SOTA：有 cap 無 value-scored allowlist&quot;">​</a></h3><ul><li><strong>Token Guard</strong>（GitHub Marketplace）：tiktoken 計數 <code>.claude/**</code>/CLAUDE.md，超 cap 失敗 PR，可設 max_tokens。<strong>無 allowlist 或 prune-diff 機制</strong>。[HIGH，親驗 Marketplace] <a href="https://github.com/marketplace/actions/token-guard-llm-token-limit-checker" target="_blank" rel="noreferrer">https://github.com/marketplace/actions/token-guard-llm-token-limit-checker</a></li><li><strong>size-limit</strong>（JS）：每 commit CI 計算 byte/time，超 limit 擲錯。<strong>「no override mechanism」</strong>——hard gate 無豁免。[HIGH，親驗 GitHub repo] <a href="https://github.com/ai/size-limit" target="_blank" rel="noreferrer">https://github.com/ai/size-limit</a></li><li><strong>ROI-weighting</strong>（Medium, Fahey 2025）：壓縮低價值段比高價值更積極——最接近 value-score 概念，但無實作工具。[MEDIUM，二手文章] <a href="https://medium.com/@fahey_james/token-budgeting-strategies-for-prompt-driven-applications-b110fb9672b9" target="_blank" rel="noreferrer">https://medium.com/@fahey_james/token-budgeting-strategies-for-prompt-driven-applications-b110fb9672b9</a></li></ul><p><strong>Insight</strong>：現有工具全是「量 + cap」，<strong>無一做「diff × value-score」</strong>。workspace 的 anchor-survival check 是這空白的具體填補。</p><hr><h2 id="_2-落點判定-擴展-3-處-均非新建" tabindex="-1">2. 落點判定：擴展 3 處，均非新建 <a class="header-anchor" href="#_2-落點判定-擴展-3-處-均非新建" aria-label="Permalink to &quot;2. 落點判定：擴展 3 處，均非新建&quot;">​</a></h2><ol><li><strong>擴展 measure.sh</strong>：加 <code>--value-check</code>，在 §R-header 存活基礎上，加 named anchor 內容非 stub 驗證（grep 條文行數 &gt; N）。healthcheck.sh 呼叫 <code>measure.sh --gate</code> 補整合缺口。確定性 R5 工作，0 新檔。</li><li><strong>擴展 autoload-evolution SKILL Phase 4</strong>：Phase 4a 後加 <code>prune-diff 驗證</code>——掃描移除行，若含 allowlist anchor（<code>^## §R[0-9]</code>、<code>Lesson YYYY-MM-DD</code>、<code>falsifiable</code>）則列出並要求使用者確認（互動式 gate）。≤20 行 diff。<strong>同時修正 L31/97/112/209 的 stale 13,000</strong>。</li><li><strong>memory-compactor 加 post-prune grep 驗證</strong>：compactor 完成後在 output（已有「壓縮前/後行數」）加 <code>grep -c &quot;^- Lesson&quot; MEMORY.md &gt;= N_before</code>。把 #448 advisor 手動 grep 自動化，填面 B 缺口。</li></ol><p>新建 SKILL 違 R2 + Lesson 2026-06-04-E。</p><hr><h2 id="_3-守衛設計骨架" tabindex="-1">3. 守衛設計骨架 <a class="header-anchor" href="#_3-守衛設計骨架" aria-label="Permalink to &quot;3. 守衛設計骨架&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>面 A — auto-load 修改後（Phase 4a / post-Edit）：</span></span>
<span class="line"><span>  [MEASURE]  wc -c 5 files → total bytes</span></span>
<span class="line"><span>  [CAP]      &gt; 19,000 → warn（soft cap；hard block 需實證計劃書）</span></span>
<span class="line"><span>  [ANCHOR-SURVIVAL]</span></span>
<span class="line"><span>    grep &quot;^## §R&quot; core.md | count == 11           → §R 條文存活</span></span>
<span class="line"><span>    grep 驗證指令 keyword (wc -c cmd) &gt; 0          → 驗證指令非 stub</span></span>
<span class="line"><span>  [PRUNE-DIFF]（僅精簡操作，互動式）</span></span>
<span class="line"><span>    diff before/after → 移除行過濾 allowlist pattern</span></span>
<span class="line"><span>    命中 → 列出 + 等待使用者 ACK；無命中 → 自動通過</span></span>
<span class="line"><span></span></span>
<span class="line"><span>面 B — MEMORY compaction 後（post-compactor）：</span></span>
<span class="line"><span>  [LESSON-COUNT]    grep -c &quot;^- Lesson&quot; after &gt;= before</span></span>
<span class="line"><span>  [TODO-SURVIVAL]   grep &quot;## 待辦&quot; after exist</span></span>
<span class="line"><span>  [RECENT-SESSIONS] 最近 5 session 標題存在</span></span>
<span class="line"><span>  有缺口 → FAIL，要求 compactor 重跑或使用者確認</span></span></code></pre></div><hr><h2 id="_4-關鍵風險與下限約束" tabindex="-1">4. 關鍵風險與下限約束 <a class="header-anchor" href="#_4-關鍵風險與下限約束" aria-label="Permalink to &quot;4. 關鍵風險與下限約束&quot;">​</a></h2><ul><li><strong>單一 canonical 單位</strong>：byte，唯一來源 core.md §Framework Integrity。SKILL.md 4 處 stale 13,000 須同步修正（優先，防三源矛盾）。</li><li><strong>R1–R12 不可丟</strong>：allowlist 最小集 = <code>^## §R[0-9]</code> × 11 + 驗證指令 keyword（<code>wc -c ... | tail -1</code> verbatim）。</li><li><strong>cap 上調須實證計劃書</strong>：守衛自身 byte 增量若造成 cap 壓力，走 evidence plan；不接受守衛反推湊 byte（core.md §Framework Integrity）。</li><li><strong>fail-open 鐵律</strong>：commit hook 只 warn；user-confirm 只在互動式 autoload-evolution Phase 4→5。</li></ul><hr><h2 id="_5-falsifiable-prediction-候選" tabindex="-1">5. Falsifiable Prediction 候選 <a class="header-anchor" href="#_5-falsifiable-prediction-候選" aria-label="Permalink to &quot;5. Falsifiable Prediction 候選&quot;">​</a></h2><ul><li>P1：注入移除 <code>## §R3</code> 的 diff → <code>measure.sh --gate</code> 或 Phase 4 守衛回 warn/非零。</li><li>P2：僅移除 TYPE-C rationale 段（無 §R、無 Lesson 行）→ 守衛靜默通過 exit 0。</li><li>P3：5 檔 total byte &gt; 19,000 → <code>measure.sh --gate</code> exit 1（已實作，需整合 healthcheck）。</li><li>P4：compactor 壓縮後 <code>grep -c &quot;^- Lesson&quot; MEMORY.md</code> 較前少 → post-prune FAIL。</li></ul><hr><h2 id="_6-信度分層彙整" tabindex="-1">6. 信度分層彙整 <a class="header-anchor" href="#_6-信度分層彙整" aria-label="Permalink to &quot;6. 信度分層彙整&quot;">​</a></h2><table tabindex="0"><thead><tr><th>來源</th><th>關鍵聲明</th><th>信度</th><th>URL</th></tr></thead><tbody><tr><td>Token Guard (Marketplace)</td><td>tiktoken cap，無 allowlist</td><td>HIGH</td><td><a href="https://github.com/marketplace/actions/token-guard-llm-token-limit-checker" target="_blank" rel="noreferrer">https://github.com/marketplace/actions/token-guard-llm-token-limit-checker</a></td></tr><tr><td>size-limit (GitHub)</td><td>hard gate「no override」</td><td>HIGH</td><td><a href="https://github.com/ai/size-limit" target="_blank" rel="noreferrer">https://github.com/ai/size-limit</a></td></tr><tr><td>ROI-weighting (Medium)</td><td>低價值段更積極壓縮</td><td>MEDIUM</td><td><a href="https://medium.com/@fahey_james/token-budgeting-strategies-for-prompt-driven-applications-b110fb9672b9" target="_blank" rel="noreferrer">https://medium.com/@fahey_james/token-budgeting-strategies-for-prompt-driven-applications-b110fb9672b9</a></td></tr><tr><td>measure.sh</td><td>--gate byte cap + §R header check</td><td>HIGH</td><td>親讀 L77-96</td></tr><tr><td>healthcheck.sh</td><td>0 measure.sh 引用（整合缺口）</td><td>HIGH</td><td>主對話 grep = 0</td></tr><tr><td>autoload-evolution SKILL.md</td><td>4 處 stale 13,000</td><td>HIGH</td><td>主對話 grep L31/97/112/209</td></tr><tr><td>MEMORY</td><td>over-prune 12 Lessons / 三源矛盾 / 545 餘裕</td><td>HIGH</td><td>repo 一手</td></tr></tbody></table><hr><h2 id="相關檔案清單" tabindex="-1">相關檔案清單 <a class="header-anchor" href="#相關檔案清單" aria-label="Permalink to &quot;相關檔案清單&quot;">​</a></h2><ul><li><code>scripts/measure.sh</code>（L77-96 byte cap + §R header；L11-13 --gate 模式）</li><li><code>scripts/healthcheck.sh</code>（整合缺口：無 measure.sh --gate 呼叫）</li><li><code>.claude/skills/autoload-evolution/SKILL.md</code>（L31/97/112/209 stale 13,000；Phase 4a 擴展點）</li><li><code>.claude/agents/memory-compactor.md</code>（「永不移除」LLM 指令，無機械驗證）</li><li><code>.claude/rules/core.md</code>（§Framework Integrity，canonical cap 定義）</li></ul>`,46)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
